//! Bringing a branch up to date with its base at merge time (PDT-328): conflicts are fixed once, when the ticket is
//! next to merge. PDT merges the base in itself; a conflict only in generated files is regenerated by the project's
//! `[[merge.regenerate]]` rules; only real conflicts go to an agent. Pure rules; pdt-api's `attempt.update_base` node
//! does the git work.

use crate::policy::ResolveConflicts;
use crate::runconfig::RegenerateDef;
use crate::ticket::PipelineStage;
use serde::{Deserialize, Serialize};
use ts_rs::TS;

/// Where an attempt is with its base's conflicts, for the ticket (in memory: `attempt.mergeUpdate`).
#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize, TS)]
#[serde(rename_all = "snake_case")]
#[ts(export)]
pub enum MergeUpdateStatus {
    /// Its pull request conflicts with the base; that is resolved at merge time.
    Deferred,
    /// PDT is merging the base in.
    Updating,
    /// An agent resolves the conflicts PDT couldn't.
    Resolving,
}

/// How a branch was brought up to date, for the ticket's timeline (a `merge_update` event's `how`).
#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize, TS)]
#[serde(rename_all = "snake_case")]
#[ts(export)]
pub enum MergeUpdateHow {
    /// A conflict was left for merge time.
    Deferred,
    /// The base merged in with no conflicts.
    Clean,
    /// Only generated files conflicted, and PDT regenerated them.
    Regenerated,
    /// Real conflicts went to an agent.
    Conflict,
    /// The agent resolved them.
    Agent,
}

/// Whether a conflict (or a base that moved) is left for merge time rather than sent to the attempt's agent now: the
/// project resolves at merge time, the ticket is in a Pipeline stage before the merge, and nobody set it to merge.
pub fn defers(policy: ResolveConflicts, stage: Option<PipelineStage>, set_to_merge: bool) -> bool {
    policy == ResolveConflicts::MergeTime
        && !set_to_merge
        && matches!(
            stage,
            Some(PipelineStage::Code | PipelineStage::Review | PipelineStage::Qa | PipelineStage::Accept)
        )
}

/// What to do with a merge's conflicted files.
#[derive(Debug, Clone, Default, PartialEq, Eq)]
pub struct Plan {
    /// The conflicted files a rule covers: PDT takes the base's side of each.
    pub generated: Vec<String>,
    /// The rules (indexes into the project's list, in its order) whose command runs once the conflicts are gone.
    pub rules: Vec<usize>,
    /// The conflicted files no rule covers: an agent's.
    pub real: Vec<String>,
}

/// Sorts `conflicted` files into the ones `rules` regenerate and the real conflicts.
pub fn plan(conflicted: &[String], rules: &[RegenerateDef]) -> Plan {
    let sets: Vec<Option<globset::GlobSet>> = rules
        .iter()
        .map(|r| {
            let mut b = globset::GlobSetBuilder::new();
            for p in &r.paths {
                b.add(crate::overlap::glob(p).ok()?);
            }
            b.build().ok()
        })
        .collect();
    let mut out = Plan::default();
    for f in conflicted {
        let path = f.replace('\\', "/");
        match sets.iter().position(|s| s.as_ref().is_some_and(|s| s.is_match(&path))) {
            Some(i) => {
                out.generated.push(f.clone());
                if !out.rules.contains(&i) {
                    out.rules.push(i);
                }
            }
            None => out.real.push(f.clone()),
        }
    }
    out.rules.sort_unstable();
    out
}

/// The most lines of conflict hunks a message to the agent carries.
pub const MAX_HUNK_LINES: usize = 400;

/// What the agent hears about conflicts PDT couldn't resolve.
pub struct ConflictNote<'a> {
    /// The base it merged (`origin/main`).
    pub base: &'a str,
    /// The files with real conflicts.
    pub files: &'a [String],
    /// `git diff` of the conflicted files (with the conflict markers).
    pub hunks: &'a str,
    /// The subjects of the commits that reached the base since the branch last had it (the tickets merged since).
    pub merged: &'a [String],
    /// The regeneration commands to run once the conflicts are resolved (generated files took the base's side).
    pub regenerate: &'a [String],
    /// A regeneration command that failed, and the end of its output.
    pub failed: Option<(&'a str, &'a str)>,
}

/// The message for the agent: the files and hunks, what merged since, and what to do.
pub fn conflict_message(n: &ConflictNote<'_>) -> String {
    let mut s = format!(
        "{} merged `{}` into this branch to merge it, and it conflicts. The merge is in progress in this worktree: \
         resolve the conflicts below, commit the merge, run the project's checks (its instructions say which) and \
         push. Change nothing else.\n",
        crate::brand::SHORT_NAME,
        n.base,
    );
    if let Some((cmd, out)) = n.failed {
        s.push_str(&format!(
            "\nOnly generated files conflicted, but regenerating them failed: `{cmd}` said\n\n```\n{}\n```\n\nFix that \
             and run it again.\n",
            out.trim_end()
        ));
    }
    if !n.files.is_empty() {
        s.push_str("\nConflicting files:\n");
        for f in n.files {
            s.push_str(&format!("- {f}\n"));
        }
    }
    if !n.regenerate.is_empty() {
        s.push_str("\nGenerated files took the base's side; once the conflicts are resolved, run:\n");
        for c in n.regenerate {
            s.push_str(&format!("- `{c}`\n"));
        }
    }
    if !n.merged.is_empty() {
        s.push_str(&format!("\nMerged into `{}` since this branch last had it:\n", n.base));
        for m in n.merged {
            s.push_str(&format!("- {m}\n"));
        }
    }
    let hunks = n.hunks.trim_end();
    if !hunks.is_empty() {
        let lines: Vec<&str> = hunks.lines().collect();
        let shown = lines.len().min(MAX_HUNK_LINES);
        s.push_str(&format!("\nThe conflicts:\n\n```diff\n{}\n```\n", lines[..shown].join("\n")));
        if lines.len() > shown {
            s.push_str(&format!("({} more lines: `git diff` shows them all.)\n", lines.len() - shown));
        }
    }
    s
}

#[cfg(test)]
mod tests {
    use super::*;

    fn rule(paths: &[&str], run: &str) -> RegenerateDef {
        RegenerateDef { paths: paths.iter().map(|p| p.to_string()).collect(), run: run.into() }
    }

    fn files(f: &[&str]) -> Vec<String> {
        f.iter().map(|s| s.to_string()).collect()
    }

    #[test]
    fn only_a_conflict_before_the_merge_step_waits_for_merge_time() {
        use PipelineStage::*;
        let m = ResolveConflicts::MergeTime;
        for stage in [Code, Review, Qa, Accept] {
            assert!(defers(m, Some(stage), false), "{stage:?}");
        }
        assert!(!defers(m, Some(Merge), false), "at the merge it is merge time");
        assert!(!defers(m, Some(MergeBlocked), false));
        assert!(!defers(m, None, false), "no pipeline: nobody would update it at merge time");
        assert!(!defers(m, Some(Code), true), "set to merge");
        assert!(!defers(ResolveConflicts::Immediately, Some(Code), false));
    }

    #[test]
    fn generated_files_are_regenerated_and_the_rest_are_real_conflicts() {
        let rules = [
            rule(&["web/src/api/gen/**"], "cargo test"),
            rule(&["Cargo.lock"], "cargo update -w"),
            rule(&["pnpm-lock.yaml"], "pnpm install"),
        ];
        let p = plan(&files(&["Cargo.lock", "web/src/api/gen/Ticket.ts"]), &rules);
        assert_eq!(p.generated, files(&["Cargo.lock", "web/src/api/gen/Ticket.ts"]));
        assert_eq!(p.rules, [0, 1], "in the project's order, each once");
        assert!(p.real.is_empty());

        let p = plan(&files(&["src/lib.rs", "Cargo.lock", "web/src/api/genx.ts"]), &rules);
        assert_eq!((p.generated, p.rules), (files(&["Cargo.lock"]), vec![1]));
        assert_eq!(p.real, files(&["src/lib.rs", "web/src/api/genx.ts"]));

        assert_eq!(plan(&files(&["a"]), &[]).real, files(&["a"]), "no rules: every conflict is real");
        assert_eq!(plan(&files(&["web\\src\\api\\gen\\A.ts"]), &rules).rules, [0], "Windows separators");
    }

    #[test]
    fn the_message_lists_files_merges_hunks_and_commands() {
        let hunks = "diff --cc a.txt\n<<<<<<< HEAD\nmine\n=======\ntheirs\n>>>>>>> origin/main\n";
        let m = conflict_message(&ConflictNote {
            base: "origin/main",
            files: &files(&["a.txt"]),
            hunks,
            merged: &files(&["PDT-1: Add a (#1)"]),
            regenerate: &files(&["cargo update -w"]),
            failed: None,
        });
        for want in ["merged `origin/main`", "- a.txt", "- PDT-1: Add a (#1)", "- `cargo update -w`", "<<<<<<< HEAD"] {
            assert!(m.contains(want), "{want} in {m}");
        }
        assert!(m.contains("run the project's checks"), "{m}");

        let long = "x\n".repeat(MAX_HUNK_LINES + 5);
        let m = conflict_message(&ConflictNote {
            base: "main",
            files: &[],
            hunks: &long,
            merged: &[],
            regenerate: &[],
            failed: Some(("pnpm install", "boom")),
        });
        assert!(m.contains("(5 more lines"), "{m}");
        assert!(m.contains("`pnpm install` said") && m.contains("boom"), "{m}");
    }
}
